import { randomBytes } from "node:crypto";
/** Fresh session id (`ses_<24 hex>` — a single safe path segment). */
export function newSessionId() {
    return `ses_${randomBytes(12).toString("hex")}`;
}
/** Fresh delivery id for one `send()` (`dlv_<24 hex>`). */
export function newDeliveryId() {
    return `dlv_${randomBytes(12).toString("hex")}`;
}
export const MAX_DELIVERY_ID_LENGTH = 256;
/**
 * The caller's {@link SendMessageOptions.deliveryId}, or a fresh one.
 * Opaque: compared verbatim, never trimmed or rewritten.
 */
export function resolveDeliveryId(requested) {
    if (requested === undefined) {
        return newDeliveryId();
    }
    if (typeof requested !== "string" ||
        requested.trim() === "" ||
        requested.length > MAX_DELIVERY_ID_LENGTH) {
        throw new TypeError(`invalid argument: deliveryId must be a non-empty string of at most ${MAX_DELIVERY_ID_LENGTH} characters`);
    }
    return requested;
}
export function newContinuationKey() {
    return randomBytes(16).toString("hex");
}
/**
 * Unique server-tool call id (a single safe path segment). Used when the
 * SDK omits `context.toolCallId` and for direct (deterministic) tool calls.
 */
export function newToolCallId(toolName) {
    const safe = toolName.replace(/[^A-Za-z0-9_]/g, "_").slice(0, 32);
    return `tool_${safe}_${randomBytes(8).toString("hex")}`;
}
/**
 * Wire form of a continuation token: the owning channel id, a colon, then
 * the channel-local key (mirrors how platform channels key sessions by
 * thread identity).
 */
export function formatContinuationToken(channelId, key) {
    return `${channelId}:${key}`;
}
export function parseContinuationToken(token) {
    const separator = token.indexOf(":");
    if (separator <= 0 || separator === token.length - 1) {
        return null;
    }
    return {
        channelId: token.slice(0, separator),
        key: token.slice(separator + 1),
    };
}
